import type { IsoTimestamp, OrgId, ProjectId, UserId } from "./common";
import type { IssuePriority } from "./issue";

/** How often a recurring rule files an issue. */
export type RecurrenceCadence = "daily" | "weekly";

/**
 * A rule the scheduler turns into an ordinary issue.
 *
 * `startsOn` and `lastOccurrenceOn` are calendar dates (`YYYY-MM-DD`) in
 * `timezone`, not instants. `weekday` is the ISO weekday (1 = Monday … 7 =
 * Sunday) and is null for a daily rule.
 */
export interface RecurringIssue {
  readonly id: string;
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly title: string;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
  readonly lastOccurrenceOn: string | null;
  readonly paused: boolean;
  readonly createdBy: UserId;
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

/**
 * Calendar-day recurrence in an IANA time zone.
 *
 * Occurrence dates are `YYYY-MM-DD` civil dates. Day D has started once the
 * local clock in that zone has reached 00:00 on D, daylight-saving included.
 * The latest started occurrence is therefore the current local date, walked
 * back to the rule's weekday when the cadence is weekly, and never a date
 * before `startsOn`.
 */

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real `YYYY-MM-DD` date, so `2026-02-30` and `2026-02-29` fail. */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (!match) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > 12 || day < 1 || day > 31) return false;

  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when `value` is an IANA zone this runtime can resolve. */
export function isIanaTimeZone(value: string): boolean {
  if (value.length === 0 || value !== value.trim()) return false;

  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

/** The civil date the clock in `timeZone` is showing at `instant`. */
export function localCalendarDate(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    calendar: "iso8601",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  let year = "";
  let month = "";
  let day = "";
  for (const part of parts) {
    if (part.type === "year") year = part.value;
    if (part.type === "month") month = part.value;
    if (part.type === "day") day = part.value;
  }

  return `${year.padStart(4, "0")}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
}

/** ISO weekday of a civil date: 1 = Monday … 7 = Sunday. */
function isoWeekday(calendarDate: string): number {
  const [year, month, day] = calendarDate.split("-").map(Number);
  const utc = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1));
  const sundayZero = utc.getUTCDay();
  return sundayZero === 0 ? 7 : sundayZero;
}

function addCalendarDays(calendarDate: string, days: number): string {
  const [year, month, day] = calendarDate.split("-").map(Number);
  const utc = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1));
  utc.setUTCDate(utc.getUTCDate() + days);

  const y = utc.getUTCFullYear().toString().padStart(4, "0");
  const m = (utc.getUTCMonth() + 1).toString().padStart(2, "0");
  const d = utc.getUTCDate().toString().padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/**
 * Latest occurrence that has already started by `now`, or null when the rule
 * has not reached its first day yet.
 */
export function latestStartedOccurrence(
  rule: {
    readonly cadence: "daily" | "weekly";
    readonly weekday: number | null;
    readonly startsOn: string;
    readonly timezone: string;
  },
  now: Date,
): string | null {
  const today = localCalendarDate(now, rule.timezone);
  if (today < rule.startsOn) return null;
  if (rule.cadence === "daily") return today;

  if (rule.weekday === null || rule.weekday < 1 || rule.weekday > 7) return null;

  const delta = (isoWeekday(today) - rule.weekday + 7) % 7;
  const candidate = addCalendarDays(today, -delta);
  if (candidate < rule.startsOn) return null;
  return candidate;
}

import { z } from "zod";
import { isCalendarDate, isIanaTimeZone } from "@/lib/recurrence";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";
import { issuePrioritySchema } from "./issue";

/**
 * Input for a new recurring-issue rule.
 *
 * `weekday` is required for a weekly cadence and forbidden for a daily one.
 * `timezone` must be an IANA zone the runtime knows, and `startsOn` must be a
 * real calendar date — `2026-02-30` is rejected, not rolled into March.
 */
export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3).max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z.string().refine(isIanaTimeZone, {
      message: "must be an IANA time zone",
    }),
    startsOn: z.string().refine(isCalendarDate, {
      message: "must be a real YYYY-MM-DD date",
    }),
  })
  .refine(
    (value) => value.cadence !== "weekly" || (value.weekday ?? null) !== null,
    {
      message: "weekday is required when cadence is weekly",
      path: ["weekday"],
    },
  )
  .refine(
    (value) => value.cadence !== "daily" || (value.weekday ?? null) === null,
    {
      message: "weekday must be null when cadence is daily",
      path: ["weekday"],
    },
  );

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;

import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const recurringIssues = sqliteTable(
  "recurring_issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    title: text("title").notNull(),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    assigneeId: text("assignee_id"),
    cadence: text("cadence", { enum: ["daily", "weekly"] }).notNull(),
    /** ISO weekday, 1 = Monday … 7 = Sunday. Null for a daily rule. */
    weekday: integer("weekday"),
    timezone: text("timezone").notNull(),
    startsOn: text("starts_on").notNull(),
    lastOccurrenceOn: text("last_occurrence_on"),
    paused: integer("paused", { mode: "boolean" }).notNull().default(false),
    createdBy: text("created_by").notNull(),
    ...timestampColumns,
  },
  (table) => [
    index("recurring_issues_org_created_idx").on(table.orgId, table.createdAt),
    index("recurring_issues_paused_idx").on(table.paused),
  ],
);

export type RecurringIssueRow = typeof recurringIssues.$inferSelect;
export type NewRecurringIssueRow = typeof recurringIssues.$inferInsert;

