/**
 * Recurring-issue rules. Org-scoped reads stay inside one tenant; the job's
 * sweep is the one cross-tenant query, same as the trial-expiry feed.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toRecurringIssue } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurrenceCadence, RecurringIssue } from "@/types/recurring-issue";

export interface InsertRecurringIssue {
  readonly orgId: OrgId;
  readonly projectId: RecurringIssue["projectId"];
  readonly title: string;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
  readonly createdBy: UserId;
}

/** Creation order, including rules that were inserted in the same millisecond. */
function creationOrder() {
  return [asc(recurringIssues.createdAt), sql`rowid`] as const;
}

export async function insertRecurringIssue(
  input: InsertRecurringIssue,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: input.createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  if (!row) throw new Error("Failed to store recurring issue");
  return toRecurringIssue(row);
}

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Every rule in the organization, oldest first. Paused rules are included. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(...creationOrder())
    .all();
  return rows.map(toRecurringIssue);
}

/**
 * Every live rule in every organization. Cross-tenant by design: the
 * recurring-issue job is the only caller.
 */
export async function listUnpausedRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(...creationOrder())
    .all();
  return rows.map(toRecurringIssue);
}

/** Paused rules count toward the plan quota. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function updateRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function updateLastOccurrenceOn(
  orgId: OrgId,
  recurringIssueId: string,
  lastOccurrenceOn: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

/**
 * Recurring issue rules: chores a background job turns into ordinary issues.
 *
 * Creating a rule validates the payload, then checks tenant scope, a live
 * project, `issue:create`, an active assignee and the plan's `recurringIssues`
 * quota. Pausing uses the same permission as creating an issue in the rule's
 * project; listing uses the same permission as reading issues.
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { orgResource, projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { Actor, Member } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

function isActiveMember(member: Member | null): member is Member {
  return member !== null && member.status === "active";
}

export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);

  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (!isActiveMember(assignee)) {
      throw new Error(
        `Assignee ${parsed.assigneeId} is not an active member of the organization`,
      );
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );
  const used = await recurringIssueRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more recurring issues`,
    );
  }

  return recurringIssueRepo.insertRecurringIssue({
    orgId: parsed.orgId,
    projectId: parsed.projectId,
    title: parsed.title,
    priority: parsed.priority,
    assigneeId: parsed.assigneeId,
    cadence: parsed.cadence,
    weekday: parsed.weekday,
    timezone: parsed.timezone,
    startsOn: parsed.startsOn,
    createdBy: actor.userId,
  });
}

export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringIssueRepo.findRecurringIssueById(
      input.orgId,
      input.recurringIssueId,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return requireFound(
    await recurringIssueRepo.updateRecurringIssuePaused(
      input.orgId,
      input.recurringIssueId,
      input.paused,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );
}

export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringIssueRepo.listRecurringIssues(orgId);
}

/**
 * Files the latest due occurrence of every live recurring-issue rule.
 *
 * Missed days are not back-filled: each rule creates at most one issue per
 * run, always for the latest occurrence whose local midnight has passed.
 * The issue is created through `createIssue` as the rule's author, so the
 * checks and the `issue.created` side effects match a hand-filed issue.
 */
import { createLogger } from "@/lib/logger";
import { can, PermissionDeniedError } from "@/lib/permissions";
import { latestStartedOccurrence } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Member } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

function isActiveMember(member: Member | null): member is Member {
  return member !== null && member.status === "active";
}

function actorFor(member: Member, orgId: OrgId): Actor {
  return { userId: member.userId, orgId, role: member.role };
}

async function assigneeStillActive(rule: RecurringIssue): Promise<UserId | null> {
  if (rule.assigneeId === null) return null;
  const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return isActiveMember(assignee) ? assignee.userId : null;
}

/**
 * Files one issue for `rule` when a new occurrence is due. Returns true only
 * when an issue was stored and `lastOccurrenceOn` advanced.
 */
async function fileOccurrence(rule: RecurringIssue, now: Date): Promise<boolean> {
  const occurrence = latestStartedOccurrence(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const creatorCanFile =
    isActiveMember(creator) &&
    can(actorFor(creator, rule.orgId), "issue:create", projectResource(project));

  if (!creatorCanFile) {
    await recurringIssueRepo.updateRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  const assigneeId = await assigneeStillActive(rule);

  try {
    await createIssue(actorFor(creator, rule.orgId), {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringIssueRepo.updateRecurringIssuePaused(rule.orgId, rule.id, true);
      return false;
    }

    logger.warn("recurring issue was not filed", {
      recurringIssueId: rule.id,
      orgId: rule.orgId,
      reason: error instanceof Error ? error.message : String(error),
    });
    return false;
  }

  await recurringIssueRepo.updateLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return true;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listUnpausedRecurringIssues();

    for (const rule of rules) {
      try {
        const filed = await fileOccurrence(rule, now);
        if (filed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue rule failed", {
          recurringIssueId: rule.id,
          orgId: rule.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

