{"type":"SearchReplace","EditsApplied":{"old_string":"","new_string":"/**
 * Files the latest due occurrence of every live recurring-issue rule.
 *
 * Missed days are not back-filled: each rule creates at most one issue per
 * run, always for the latest occurrence whose local midnight has passed.
 * The issue is created through `createIssue` as the rule's author, so the
 * checks and the `issue.created` side effects match a hand-filed issue.
 */
import { createLogger } from "@/lib/logger";
import { can, PermissionDeniedError } from "@/lib/permissions";
import { latestStartedOccurrence } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Member } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

function isActiveMember(member: Member | null): member is Member {
  return member !== null && member.status === "active";
}

function actorFor(member: Member, orgId: OrgId): Actor {
  return { userId: member.userId, orgId, role: member.role };
}

async function assigneeStillActive(rule: RecurringIssue): Promise<UserId | null> {
  if (rule.assigneeId === null) return null;
  const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return isActiveMember(assignee) ? assignee.userId : null;
}

/**
 * Files one issue for `rule` when a new occurrence is due. Returns true only
 * when an issue was stored and `lastOccurrenceOn` advanced.
 */
async function fileOccurrence(rule: RecurringIssue, now: Date): Promise<boolean> {
  const occurrence = latestStartedOccurrence(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const creatorCanFile =
    isActiveMember(creator) &&
    can(actorFor(creator, rule.orgId), "issue:create", projectResource(project));

  if (!creatorCanFile) {
    await recurringIssueRepo.updateRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  const assigneeId = await assigneeStillActive(rule);

  try {
    await createIssue(actorFor(creator, rule.orgId), {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringIssueRepo.updateRecurringIssuePaused(rule.orgId, rule.id, true);
      return false;
    }

    logger.warn("recurring issue was not filed", {
      recurringIssueId: rule.id,
      orgId: rule.orgId,
      reason: error instanceof Error ? error.message : String(error),
    });
    return false;
  }

  await recurringIssueRepo.updateLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return true;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listUnpausedRecurringIssues();

    for (const rule of rules) {
      try {
        const filed = await fileOccurrence(rule, now);
        if (filed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue rule failed", {
          recurringIssueId: rule.id,
          orgId: rule.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
