import { ZodError } from "zod";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { UNLIMITED, getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { latestStartedOccurrence, localCalendarDate } from "@/lib/recurrence";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import { runMigrations } from "@/server/db/migrate";
import { enqueue, drain, resetQueue } from "@/server/jobs/queue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { NotFoundError } from "@/server/services/_support";
import { subscribe } from "@/lib/event-bus";
import * as recurringIssueService from "@/server/services/recurring-issue-service";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { toIsoTimestamp } from "@/types/common";
import { createTenant } from "@/tests-fixtures";

// The fixture module lives under tests/; import via a relative alias set below.
void createTenant;

const failures: string[] = [];
function check(name: string, ok: boolean, detail = ""): void {
  if (!ok) failures.push(`${name}${detail ? `: ${detail}` : ""}`);
  else console.log(`ok  ${name}`);
}

const ULID = "01HZZZAAAAAAAAAAAAAAAAAAAA";

function base(overrides: Record<string, unknown> = {}) {
  return {
    orgId: ULID,
    projectId: ULID,
    title: "Daily triage",
    cadence: "daily",
    timezone: "UTC",
    startsOn: "2026-03-05",
    ...overrides,
  };
}

// --- schema ---
{
  const parsed = createRecurringIssueSchema.parse(base());
  check("defaults", parsed.priority === "none" && parsed.assigneeId === null && parsed.weekday === null);
  check("weekly ok", createRecurringIssueSchema.safeParse(base({ cadence: "weekly", weekday: 1 })).success);
  check("weekly 7", createRecurringIssueSchema.safeParse(base({ cadence: "weekly", weekday: 7 })).success);
  check("weekly null", !createRecurringIssueSchema.safeParse(base({ cadence: "weekly", weekday: null })).success);
  check("weekly omit", !createRecurringIssueSchema.safeParse(base({ cadence: "weekly" })).success);
  check("daily weekday", !createRecurringIssueSchema.safeParse(base({ weekday: 1 })).success);
  check("daily explicit null", createRecurringIssueSchema.safeParse(base({ weekday: null })).success);
  check("feb 30", !createRecurringIssueSchema.safeParse(base({ startsOn: "2026-02-30" })).success);
  check("2026 not leap", !createRecurringIssueSchema.safeParse(base({ startsOn: "2026-02-29" })).success);
  check("2024 leap", createRecurringIssueSchema.safeParse(base({ startsOn: "2024-02-29" })).success);
  check("apr 31", !createRecurringIssueSchema.safeParse(base({ startsOn: "2026-04-31" })).success);
  check("bad shape", !createRecurringIssueSchema.safeParse(base({ startsOn: "2026-3-05" })).success);
  check("bad zone", !createRecurringIssueSchema.safeParse(base({ timezone: "Not/AZone" })).success);
  check("utc", createRecurringIssueSchema.safeParse(base({ timezone: "UTC" })).success);
  check("ny", createRecurringIssueSchema.safeParse(base({ timezone: "America/New_York" })).success);
  check("tokyo", createRecurringIssueSchema.safeParse(base({ timezone: "Asia/Tokyo" })).success);
  check("short title", !createRecurringIssueSchema.safeParse(base({ title: "ab" })).success);
  check("title 180", createRecurringIssueSchema.safeParse(base({ title: "a".repeat(180) })).success);
  check("title 181", !createRecurringIssueSchema.safeParse(base({ title: "a".repeat(181) })).success);
  check("weekday 0", !createRecurringIssueSchema.safeParse(base({ cadence: "weekly", weekday: 0 })).success);
  check("weekday 8", !createRecurringIssueSchema.safeParse(base({ cadence: "weekly", weekday: 8 })).success);
  check("weekday 1.5", !createRecurringIssueSchema.safeParse(base({ cadence: "weekly", weekday: 1.5 })).success);
  check("bad priority", !createRecurringIssueSchema.safeParse(base({ priority: "critical" })).success);
  check("bad org", !createRecurringIssueSchema.safeParse(base({ orgId: "acme" })).success);

  let threw = false;
  try {
    createRecurringIssueSchema.parse(base({ startsOn: "2026-02-30" }));
  } catch (error) {
    threw = error instanceof ZodError;
  }
  check("parse throws ZodError", threw);
}

// --- calendar ---
{
  const utcMidnight = new Date("2026-03-05T00:00:00.000Z");
  const utcBefore = new Date("2026-03-04T23:59:59.999Z");
  check("utc midnight", localCalendarDate(utcMidnight, "UTC") === "2026-03-05");
  check("utc before", localCalendarDate(utcBefore, "UTC") === "2026-03-04");

  const estMidnight = new Date("2026-03-05T05:00:00.000Z");
  const estBefore = new Date("2026-03-05T04:59:59.999Z");
  check("est midnight", localCalendarDate(estMidnight, "America/New_York") === "2026-03-05");
  check("est before", localCalendarDate(estBefore, "America/New_York") === "2026-03-04");

  // DST spring forward 2026-03-08 02:00 EST -> 03:00 EDT
  const duringGap = new Date("2026-03-08T07:00:00.000Z"); // 03:00 EDT
  const beforeGap = new Date("2026-03-08T06:59:00.000Z"); // 01:59 EST
  check("dst spring date", localCalendarDate(duringGap, "America/New_York") === "2026-03-08");
  check("dst spring before", localCalendarDate(beforeGap, "America/New_York") === "2026-03-08");
  const beforeMar8 = new Date("2026-03-08T04:59:00.000Z"); // Mar 7 23:59 EST
  check("before mar 8", localCalendarDate(beforeMar8, "America/New_York") === "2026-03-07");

  // Fall back 2026-11-01
  const repeated = new Date("2026-11-01T06:30:00.000Z"); // 01:30 EST
  check("fall back", localCalendarDate(repeated, "America/New_York") === "2026-11-01");

  const tokyoMidnight = new Date("2026-03-04T15:00:00.000Z");
  const tokyoBefore = new Date("2026-03-04T14:59:59.999Z");
  check("tokyo midnight", localCalendarDate(tokyoMidnight, "Asia/Tokyo") === "2026-03-05");
  check("tokyo before", localCalendarDate(tokyoBefore, "Asia/Tokyo") === "2026-03-04");

