import { TenantScopeError } from "@/lib/tenant";
import { getDb, members, recurringIssues } from "@/server/db";
import { drain, enqueue, resetQueue } from "@/server/jobs/queue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import { tick } from "@/server/jobs/scheduler";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { NotFoundError } from "@/server/services/_support";
import * as recurringIssueService from "@/server/services/recurring-issue-service";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Tenant } from "../tests/server/_support/fixtures";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../tests/server/_support/fixtures";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

async function pauseAll(): Promise<void> {
  const rules = await recurringIssueRepo.listUnpausedRecurringIssues();
  for (const rule of rules) {
    await recurringIssueRepo.updateRecurringIssuePaused(rule.orgId, rule.id, true);
  }
}

async function issuesIn(orgId: OrgId, projectId: ProjectId) {
  const page = await issueRepo.listIssues({ orgId, projectId, limit: 100 });
  return page.items;
}

function ruleInput(
  tenant: Tenant,
  overrides: Record<string, unknown> = {},
) {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    title: "Daily triage",
    cadence: "daily" as const,
    timezone: "UTC",
    startsOn: "2026-03-05",
    ...overrides,
  };
}

async function main(): Promise<void> {
  const cleanup = await useTemporaryDatabase();
  try {
    const growth = await createTenant("growth", "growth");
    const other = await createTenant("other", "growth");
    const free = await createTenant("freebie", "free");
    const starter = await createTenant("starter", "starter");

    // Invalid input stores nothing.
    let zod = false;
    try {
      await recurringIssueService.createRecurringIssue(
        growth.actors.member,
        ruleInput(growth, { startsOn: "2026-02-30" }),
      );
    } catch (error) {
      zod = error instanceof ZodError;
    }
    assert(zod, "invalid startsOn should throw ZodError");
    assert(
      (await recurringIssueRepo.countRecurringIssues(growth.org.id)) === 0,
      "zod failure stored a row",
    );

    // Tenant scope.
    let scope = false;
    try {
      await recurringIssueService.createRecurringIssue(
        growth.actors.member,
        ruleInput(other),
      );
    } catch (error) {
      scope = error instanceof TenantScopeError;
    }
    assert(scope, "cross-tenant create should throw TenantScopeError");
    assert(
      (await recurringIssueRepo.countRecurringIssues(other.org.id)) === 0,
      "cross-tenant create stored a row",
    );

    // Missing project.
    let missing = false;
    try {
      await recurringIssueService.createRecurringIssue(growth.actors.member, {
        ...ruleInput(growth),
        projectId: "01HZZZBBBBBBBBBBBBBBBBBBBB" as ProjectId,
      });
    } catch (error) {
      missing = error instanceof NotFoundError;
    }
    assert(missing, "missing project should be NotFoundError");

    // Archived project.
    await projectRepo.archiveProject(growth.org.id, growth.project.id);
    let archived = false;
    try {
      await recurringIssueService.createRecurringIssue(
        growth.actors.member,
        ruleInput(growth),
      );
    } catch (error) {
      archived = error instanceof AlreadyArchivedError;
    }
    assert(archived, "archived project should throw AlreadyArchivedError");
    await projectRepo.restoreProject(growth.org.id, growth.project.id);

    // Viewer cannot create; can list.
    let denied = false;
    try {
      await recurringIssueService.createRecurringIssue(
        growth.actors.viewer,
        ruleInput(growth),
      );
    } catch (error) {
      denied = error instanceof PermissionDeniedError;
    }
    assert(denied, "viewer create should be permission denied");
    assert(
      (await recurringIssueService.listRecurringIssues(
        growth.actors.viewer,
        growth.org.id,
      )).length === 0,
      "viewer should be allowed to list",
    );

    // Bad assignee stores nothing.
    let badAssignee = false;
    try {
      await recurringIssueService.createRecurringIssue(growth.actors.member, {
        ...ruleInput(growth),
        assigneeId: other.userIds.member,
      });
    } catch (error) {
      badAssignee = error instanceof Error && !(error instanceof ZodError);
    }
    assert(badAssignee, "inactive assignee should reject");
    assert(
      (await recurringIssueRepo.countRecurringIssues(growth.org.id)) === 0,
      "bad assignee stored a row",
    );

    // Free plan quota is zero.
    let freeBlocked = false;
    try {
      await recurringIssueService.createRecurringIssue(
        free.actors.owner,
        ruleInput(free),
      );
    } catch (error) {
      freeBlocked = error instanceof Error;
    }
    assert(freeBlocked, "free plan should reject the first rule");
    assert(
      (await recurringIssueRepo.countRecurringIssues(free.org.id)) === 0,
      "free plan stored a row",
    );

    // Starter cap is 3, paused rules included.
    const starterRules = [];
    for (let index = 0; index < 3; index += 1) {
      starterRules.push(
        await recurringIssueService.createRecurringIssue(starter.actors.member, {
          ...ruleInput(starter),
          title: `Starter chore ${index}`,
        }),
      );
    }
    let starterBlocked = false;
    try {
      await recurringIssueService.createRecurringIssue(
        starter.actors.member,
        ruleInput(starter, { title: "Starter chore extra" }),
      );
    } catch (error) {
      starterBlocked = error instanceof Error;
    }
    assert(starterBlocked, "starter should reject the fourth rule");
    assert(
      (await recurringIssueRepo.countRecurringIssues(starter.org.id)) === 3,
      "fourth starter rule was stored",
    );
    await recurringIssueService.setRecurringIssuePaused(starter.actors.member, {
      orgId: starter.org.id,
      recurringIssueId: starterRules[0]!.id,
      paused: true,
    });
    let stillBlocked = false;
    try {
      await recurringIssueService.createRecurringIssue(
        starter.actors.member,
        ruleInput(starter, { title: "Starter chore extra" }),
      );
    } catch {
      stillBlocked = true;
    }
    assert(stillBlocked, "paused rules must still count toward the cap");

    await pauseAll();

    // Happy-path create, list order, pause permission.
    const first = await recurringIssueService.createRecurringIssue(
      growth.actors.admin,
      {
        ...ruleInput(growth),
        title: "Daily triage",
        priority: "high",
        assigneeId: growth.userIds.member,
      },
    );
    const second = await recurringIssueService.createRecurringIssue(
      growth.actors.member,
      ruleInput(growth, { title: "Second chore", cadence: "weekly", weekday: 1 }),
    );
    assert(first.paused === false && typeof first.paused === "boolean", "paused flag");
    assert(first.lastOccurrenceOn === null, "lastOccurrence starts null");
    assert(first.createdBy === growth.actors.admin.userId, "createdBy is the actor");
    assert(first.priority === "high", "priority stored");
    assert(first.assigneeId === growth.userIds.member, "assignee stored");
    assert(first.weekday === null, "daily weekday is null");
    assert(second.weekday === 1 && second.cadence === "weekly", "weekly weekday");

    const listed = await recurringIssueService.listRecurringIssues(
      growth.actors.viewer,
      growth.org.id,
    );
    assert(
      listed.map((rule) => rule.id).join(",") === [first.id, second.id].join(","),
      `list order ${listed.map((rule) => rule.id).join(",")} vs ${first.id},${second.id}`,
    );

    let viewerPause = false;
    try {
      await recurringIssueService.setRecurringIssuePaused(growth.actors.viewer, {
        orgId: growth.org.id,
        recurringIssueId: first.id,
        paused: true,
      });
    } catch (error) {
      viewerPause = error instanceof PermissionDeniedError;
    }
    assert(viewerPause, "viewer cannot pause");

    let unknown = false;
    try {
      await recurringIssueService.setRecurringIssuePaused(growth.actors.member, {
        orgId: growth.org.id,
        recurringIssueId: "does-not-exist",
        paused: true,
      });
    } catch (error) {
      unknown = error instanceof NotFoundError;
    }
    assert(unknown, "missing rule is not found");

    let otherOrg = false;
    try {
      await recurringIssueService.setRecurringIssuePaused(other.actors.owner, {
        orgId: growth.org.id,
        recurringIssueId: first.id,
        paused: true,
      });
    } catch (error) {
      otherOrg = error instanceof TenantScopeError;
    }
    assert(otherOrg, "pause across orgs is tenant scope");

    let hidden = false;
    try {
      await recurringIssueService.setRecurringIssuePaused(other.actors.owner, {
        orgId: other.org.id,
        recurringIssueId: first.id,
        paused: true,
      });
    } catch (error) {
      hidden = error instanceof NotFoundError;
    }
    assert(hidden, "another org's rule id is not found inside this org");

    const paused = await recurringIssueService.setRecurringIssuePaused(
      growth.actors.member,
      { orgId: growth.org.id, recurringIssueId: second.id, paused: true },
    );
    assert(paused.paused === true, "pause sticks");
    const resumed = await recurringIssueService.setRecurringIssuePaused(
      growth.actors.admin,
      { orgId: growth.org.id, recurringIssueId: second.id, paused: false },
    );
    assert(resumed.paused === false, "unpause sticks");

    await pauseAll();

    // Job: daily, one issue, idempotent, no backfill, events.
    const daily = await recurringIssueService.createRecurringIssue(
      growth.actors.member,
      {
        ...ruleInput(growth),
        title: "Daily triage",
        priority: "urgent",
        assigneeId: growth.userIds.member,
        startsOn: "2026-03-01",
      },
    );
    const now = new Date("2026-03-05T15:00:00.000Z");
    const seen: { actorId: string | null; title: string; assigneeId: string | null; priority: string }[] = [];
    const off = subscribe("issue.created", (payload) => {
      seen.push({
        actorId: payload.actorId,
        title: payload.title,
        assigneeId: payload.assigneeId,
        priority: payload.priority,
      });
    });
    const firstRun = await runRecurringIssueJob(now);
    off();
    assert(firstRun.processed === 1 && firstRun.failed === 0, `first run ${JSON.stringify(firstRun)}`);
    assert(firstRun.kind === "recurring-issues", "job kind");
    const filed = await issuesIn(growth.org.id, growth.project.id);
    assert(filed.length === 1, `expected 1 issue, got ${filed.length}`);
    assert(filed[0]?.title === "Daily triage (2026-03-05)", `title ${filed[0]?.title}`);
    assert(filed[0]?.status === "backlog", "status backlog");
    assert(filed[0]?.priority === "urgent", "priority");
    assert(filed[0]?.description === null, "no description");
    assert(filed[0]?.dueAt === null, "no due date");
    assert(filed[0]?.labelIds.length === 0, "no labels");
    assert(filed[0]?.assigneeId === growth.userIds.member, "assignee kept");
    assert(filed[0]?.authorId === growth.userIds.member, "author is the creator");
    assert(seen.length === 1 && seen[0]?.actorId === growth.userIds.member, "event actor");
    assert(seen[0]?.title === "Daily triage (2026-03-05)", "event title");
    const after = await recurringIssueRepo.findRecurringIssueById(growth.org.id, daily.id);
    assert(after?.lastOccurrenceOn === "2026-03-05", "last occurrence advanced");
    assert(after?.paused === false, "not paused");

    const again = await runRecurringIssueJob(now);
    assert(again.processed === 0, "second run for the same now creates nothing");
    assert((await issuesIn(growth.org.id, growth.project.id)).length === 1, "still one issue");

    const later = await runRecurringIssueJob(new Date("2026-03-09T00:00:00.000Z"));
    assert(later.processed === 1, "next day files once");
    const titles = (await issuesIn(growth.org.id, growth.project.id)).map((issue) => issue.title).sort();
    assert(
      titles.join("|") === "Daily triage (2026-03-05)|Daily triage (2026-03-09)",
      `backfill titles ${titles.join("|")}`,
    );

    await pauseAll();

    // Weekly latest Monday only.
    await recurringIssueService.createRecurringIssue(growth.actors.owner, {
      ...ruleInput(growth),
      title: "Weekly sync",
      cadence: "weekly",
      weekday: 1,
      startsOn: "2026-03-02",
    });
    const weekly = await runRecurringIssueJob(new Date("2026-03-20T12:00:00.000Z"));
    assert(weekly.processed === 1, "weekly processed");
    const weeklyIssues = await issuesIn(growth.org.id, growth.project.id);
    const weeklyTitles = weeklyIssues.map((issue) => issue.title);
    assert(
      weeklyTitles.includes("Weekly sync (2026-03-16)"),
      `weekly title ${weeklyTitles.join("|")}`,
    );
    assert(
      !weeklyTitles.some((title) => title.includes("2026-03-02") || title.includes("2026-03-09")),
      "weekly did not backfill",
    );

    await pauseAll();

    // Timezone: New York midnight.
    await recurringIssueService.createRecurringIssue(growth.actors.owner, {
      ...ruleInput(growth),
      title: "NY standup",
      timezone: "America/New_York",
      startsOn: "2026-03-05",
    });
    const beforeNy = await runRecurringIssueJob(new Date("2026-03-05T04:30:00.000Z"));
    assert(beforeNy.processed === 0, "NY day has not started");
    const atNy = await runRecurringIssueJob(new Date("2026-03-05T05:00:00.000Z"));
    assert(atNy.processed === 1, "NY midnight files");
    const nyTitles = (await issuesIn(growth.org.id, growth.project.id)).map((issue) => issue.title);
    assert(nyTitles.includes("NY standup (2026-03-05)"), `ny titles ${nyTitles.join("|")}`);

    await pauseAll();

    // Archived project is skipped and not paused; restore files the then-latest day.
    const archRule = await recurringIssueService.createRecurringIssue(growth.actors.owner, {
      ...ruleInput(growth),
      title: "After restore",
      startsOn: "2026-03-01",
    });
    await projectRepo.archiveProject(growth.org.id, growth.project.id);
    const skipped = await runRecurringIssueJob(new Date("2026-03-05T12:00:00.000Z"));
    assert(skipped.processed === 0, "archived project files nothing");
    const skippedRule = await recurringIssueRepo.findRecurringIssueById(growth.org.id, archRule.id);
    assert(skippedRule?.paused === false, "archive does not pause");
    assert(skippedRule?.lastOccurrenceOn === null, "archive does not advance");
    await projectRepo.restoreProject(growth.org.id, growth.project.id);
    const restored = await runRecurringIssueJob(new Date("2026-03-09T12:00:00.000Z"));
    assert(restored.processed === 1, "restored project files the latest day");
    const restoredTitles = (await issuesIn(growth.org.id, growth.project.id)).map((issue) => issue.title);
    assert(
      restoredTitles.includes("After restore (2026-03-09)"),
      `restore titles ${restoredTitles.join("|")}`,
    );
    assert(
      !restoredTitles.includes("After restore (2026-03-05)"),
      "restore does not backfill the skipped day",
    );

    await pauseAll();

    // Creator demoted to viewer: pause, no issue.
    const demotedRule = await recurringIssueService.createRecurringIssue(growth.actors.member, {
      ...ruleInput(growth),
      title: "Demoted",
      startsOn: "2026-03-01",
    });
    const memberRow = await memberRepo.findMember(growth.org.id, growth.userIds.member);
    assert(memberRow, "member row");
    await memberRepo.updateMemberRole(growth.org.id, memberRow.id, "viewer");
    const demotedRun = await runRecurringIssueJob(new Date("2026-03-05T12:00:00.000Z"));
    assert(demotedRun.processed === 0, "demoted creator files nothing");
    const demotedAfter = await recurringIssueRepo.findRecurringIssueById(
      growth.org.id,
      demotedRule.id,
    );
    assert(demotedAfter?.paused === true, "demoted rule is paused");
    assert(demotedAfter?.lastOccurrenceOn === null, "demoted rule does not advance");
    assert(
      !(await issuesIn(growth.org.id, growth.project.id)).some((issue) => issue.title.startsWith("Demoted")),
      "no demoted issue",
    );
    await memberRepo.updateMemberRole(growth.org.id, memberRow.id, "member");

    await pauseAll();

    // Suspended creator pauses.
    const suspendedRule = await recurringIssueService.createRecurringIssue(growth.actors.member, {
      ...ruleInput(growth),
      title: "Suspended creator",
      startsOn: "2026-03-01",
    });
    getDb()
      .update(members)
      .set({ status: "suspended" })
      .where(eq(members.userId, growth.userIds.member))
      .run();
    await runRecurringIssueJob(new Date("2026-03-05T12:00:00.000Z"));
    const suspendedAfter = await recurringIssueRepo.findRecurringIssueById(
      growth.org.id,
      suspendedRule.id,
    );
    assert(suspendedAfter?.paused === true, "suspended creator pauses the rule");
    getDb()
      .update(members)
      .set({ status: "active" })
      .where(eq(members.userId, growth.userIds.member))
      .run();

    await pauseAll();

    // Removed creator pauses.
    const removedRule = await recurringIssueService.createRecurringIssue(growth.actors.admin, {
      ...ruleInput(growth),
      title: "Removed creator",
      startsOn: "2026-03-01",
    });
    const adminRow = await memberRepo.findMember(growth.org.id, growth.userIds.admin);
    assert(adminRow, "admin row");
    await memberRepo.archiveMember(growth.org.id, adminRow.id);
    await runRecurringIssueJob(new Date("2026-03-05T12:00:00.000Z"));
    const removedAfter = await recurringIssueRepo.findRecurringIssueById(
      growth.org.id,
      removedRule.id,
    );
    assert(removedAfter?.paused === true, "removed creator pauses the rule");

    await pauseAll();

    // Inactive assignee is dropped; rule stays live.
    const assignRule = await recurringIssueService.createRecurringIssue(growth.actors.owner, {
      ...ruleInput(growth),
      title: "Unassign me",
      assigneeId: growth.userIds.member,
      startsOn: "2026-03-01",
    });
    getDb()
      .update(members)
      .set({ status: "suspended" })
      .where(eq(members.userId, growth.userIds.member))
      .run();
    const unassignedRun = await runRecurringIssueJob(new Date("2026-03-06T12:00:00.000Z"));
    assert(unassignedRun.processed === 1, "inactive assignee still files");
    const unassigned = (await issuesIn(growth.org.id, growth.project.id)).find((issue) =>
      issue.title.startsWith("Unassign me"),
    );
    assert(unassigned?.assigneeId === null, "assignee cleared");
    const assignAfter = await recurringIssueRepo.findRecurringIssueById(growth.org.id, assignRule.id);
    assert(assignAfter?.paused === false, "assignee loss does not pause");
    assert(assignAfter?.assigneeId === growth.userIds.member, "rule assignee unchanged");
    assert(assignAfter?.lastOccurrenceOn === "2026-03-06", "occurrence recorded");
    getDb()
      .update(members)
      .set({ status: "active" })
      .where(eq(members.userId, growth.userIds.member))
      .run();

    await pauseAll();

    // Issue quota refusal leaves the rule untouched and does not block the sibling.
    const quotaRule = await recurringIssueRepo.insertRecurringIssue({
      orgId: free.org.id,
      projectId: free.project.id,
      title: "Over quota",
      priority: "low",
      assigneeId: null,
      cadence: "daily",
      weekday: null,
      timezone: "UTC",
      startsOn: "2026-03-01",
      createdBy: free.userIds.owner,
    });
    for (let index = 0; index < 100; index += 1) {
      const number = await issueRepo.nextIssueNumber(free.org.id, free.project.id);
      await issueRepo.insertIssue(
        issueInput(free.org.id, free.project.id, { title: `Filler ${index}` }),
        free.userIds.owner,
        number,
      );
    }
    const sibling = await recurringIssueService.createRecurringIssue(other.actors.member, {
      ...ruleInput(other),
      title: "Sibling",
      startsOn: "2026-03-01",
    });
    const mixed = await runRecurringIssueJob(new Date("2026-03-08T12:00:00.000Z"));
    assert(mixed.processed === 1 && mixed.failed === 0, `mixed run ${JSON.stringify(mixed)}`);
    const quotaAfter = await recurringIssueRepo.findRecurringIssueById(free.org.id, quotaRule.id);
    assert(quotaAfter?.paused === false, "quota does not pause");
    assert(quotaAfter?.lastOccurrenceOn === null, "quota does not advance");
    assert(
      (await issueRepo.countIssues(free.org.id, free.project.id)) === 100,
      "quota created an issue",
    );
    const siblingIssues = await issuesIn(other.org.id, other.project.id);
    assert(
      siblingIssues.some((issue) => issue.title === "Sibling (2026-03-08)"),
      "sibling was filed",
    );
    void sibling;

    await pauseAll();

    // Paused rules are ignored.
    const quiet = await recurringIssueService.createRecurringIssue(growth.actors.owner, {
      ...ruleInput(growth),
      title: "Quiet",
      startsOn: "2026-03-01",
    });
    await recurringIssueRepo.updateRecurringIssuePaused(growth.org.id, quiet.id, true);
    const quietRun = await runRecurringIssueJob(new Date("2026-03-10T12:00:00.000Z"));
    assert(quietRun.processed === 0, "paused rule is skipped");

    await pauseAll();

    // Queue dispatches the kind with the current time.
    const queuedRule = await recurringIssueService.createRecurringIssue(growth.actors.owner, {
      ...ruleInput(growth),
      title: "Queued",
      startsOn: "2020-01-01",
    });
    resetQueue();
    enqueue({
      id: "recurring-issues:check",
      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });
    const completed = await drain();
    assert(completed === 1, `drain completed ${completed}`);
    const today = localCalendarDate(new Date(), "UTC");
    const queuedIssues = await issuesIn(growth.org.id, growth.project.id);
    assert(
      queuedIssues.some((issue) => issue.title === `Queued (${today})`),
      `queue title missing ${today} in ${queuedIssues.map((issue) => issue.title).join("|")}`,
    );
    const queuedAfter = await recurringIssueRepo.findRecurringIssueById(
      growth.org.id,
      queuedRule.id,
    );
    assert(queuedAfter?.lastOccurrenceOn === today, "queue advanced last occurrence");

    resetQueue();
    enqueue({
      id: "recurring-issues:check-2",
      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });
    await drain();
    const afterSecond = await issuesIn(growth.org.id, growth.project.id);
    assert(
      afterSecond.filter((issue) => issue.title.startsWith("Queued")).length === 1,
      "queue rerun created a duplicate",
    );

    // Scheduler cadence is 15 minutes.
    getDb()
      .update(recurringIssues)
      .set({ lastOccurrenceOn: null })
      .where(eq(recurringIssues.id, queuedRule.id))
      .run();
    const t0 = new Date(Date.now() - 60 * 60 * 1000);
    await tick(t0);
    const afterTick = (await issuesIn(growth.org.id, growth.project.id)).filter((issue) =>
      issue.title.startsWith("Queued"),
    );
    assert(afterTick.length === 2, `tick should file again, got ${afterTick.length}`);

    getDb()
      .update(recurringIssues)
      .set({ lastOccurrenceOn: null })
      .where(eq(recurringIssues.id, queuedRule.id))
      .run();
    await tick(new Date(t0.getTime() + 10 * 60 * 1000));
    const afterTen = (await issuesIn(growth.org.id, growth.project.id)).filter((issue) =>
      issue.title.startsWith("Queued"),
    );
