      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });
    const completed = await drain();
    assert(completed === 1, `drain completed ${completed}`);
    const today = localCalendarDate(new Date(), "UTC");
    const queuedIssues = await issuesIn(growth.org.id, growth.project.id);
    assert(
      queuedIssues.some((issue) => issue.title === `Queued (${today})`),
      `queue title missing ${today} in ${queuedIssues.map((issue) => issue.title).join("|")}`,
    );
    const queuedAfter = await recurringIssueRepo.findRecurringIssueById(
      growth.org.id,
      queuedRule.id,
    );
    assert(queuedAfter?.lastOccurrenceOn === today, "queue advanced last occurrence");

    resetQueue();
    enqueue({
      id: "recurring-issues:check-2",
      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });
    await drain();
    const afterSecond = await issuesIn(growth.org.id, growth.project.id);
    assert(
      afterSecond.filter((issue) => issue.title.startsWith("Queued")).length === 1,
      "queue rerun created a duplicate",
    );

    // Scheduler cadence is 15 minutes.
    getDb()
      .update(recurringIssues)
      .set({ lastOccurrenceOn: null })
      .where(eq(recurringIssues.id, queuedRule.id))
      .run();
    const t0 = new Date(Date.now() - 60 * 60 * 1000);
    await tick(t0);
    const afterTick = (await issuesIn(growth.org.id, growth.project.id)).filter((issue) =>
      issue.title.startsWith("Queued"),
    );
    assert(afterTick.length === 2, `tick should file again, got ${afterTick.length}`);

    getDb()
      .update(recurringIssues)
      .set({ lastOccurrenceOn: null })
      .where(eq(recurringIssues.id, queuedRule.id))
      .run();
    await tick(new Date(t0.getTime() + 10 * 60 * 1000));
    const afterTen = (await issuesIn(growth.org.id, growth.project.id)).filter((issue) =>
      issue.title.startsWith("Queued"),
    );
    assert(afterTen.length === 2, `10 min tick should wait, got ${afterTen.length}`);

    await tick(new Date(t0.getTime() + 15 * 60 * 1000));
    const afterFifteen = (await issuesIn(growth.org.id, growth.project.id)).filter((issue) =>
      issue.title.startsWith("Queued"),
    );
    assert(afterFifteen.length === 3, `15 min tick should file, got ${afterFifteen.length}`);

    console.log("integration checks passed");
  } finally {
    cleanup();
  }
}

await main();
